// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/otp-challenges", wrapper.RequestOtp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/sessions", wrapper.CreateSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/sessions/refresh", wrapper.RefreshSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/sessions/current/sign-out", wrapper.SignOut)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me/devices", wrapper.ListDevices)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/me/devices/{deviceId}/revoke", wrapper.RevokeDevice)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/me/devices/{deviceId}/approve", wrapper.ApproveDevice)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/me/devices/current/push-token", wrapper.SetPushToken)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/mfa/totp", wrapper.EnrolTotp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/mfa/totp/confirm", wrapper.ConfirmTotp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/mfa/verify", wrapper.VerifyMfa)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/step-up", wrapper.StepUp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/step-up/otp-challenges", wrapper.RequestStepUpOtp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/step-up/otp", wrapper.VerifyStepUpOtp)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me/profile", wrapper.GetProfile)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/me/profile", wrapper.PutProfile)
	})

	return r
}

