// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// EnrolTotp Start authenticator set-up (professionals)
	// (POST /v1/auth/mfa/totp)
	EnrolTotp(ctx context.Context, request EnrolTotpRequestObject) (EnrolTotpResponseObject, error)
	// ConfirmTotp Confirm set-up with a first code
	// (POST /v1/auth/mfa/totp/confirm)
	ConfirmTotp(ctx context.Context, request ConfirmTotpRequestObject) (ConfirmTotpResponseObject, error)
	// VerifyMfa Complete MFA for this session
	// (POST /v1/auth/mfa/verify)
	VerifyMfa(ctx context.Context, request VerifyMfaRequestObject) (VerifyMfaResponseObject, error)
	// RequestOtp Send a sign-in code by SMS (template SMS-01)
	// (POST /v1/auth/otp-challenges)
	RequestOtp(ctx context.Context, request RequestOtpRequestObject) (RequestOtpResponseObject, error)
	// CreateSession Verify the code and sign in on this device (creates the account if new)
	// (POST /v1/auth/sessions)
	CreateSession(ctx context.Context, request CreateSessionRequestObject) (CreateSessionResponseObject, error)
	// SignOut End this session
	// (POST /v1/auth/sessions/current/sign-out)
	SignOut(ctx context.Context, request SignOutRequestObject) (SignOutResponseObject, error)
	// RefreshSession Rotate tokens with a proof signed by the bound device key
	// (POST /v1/auth/sessions/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// StepUp Re-authenticate before signing or other sensitive actions (P08)
	// (POST /v1/auth/step-up)
	StepUp(ctx context.Context, request StepUpRequestObject) (StepUpResponseObject, error)
	// VerifyStepUpOtp Verify the step-up code (patients); valid for 5 minutes
	// (POST /v1/auth/step-up/otp)
	VerifyStepUpOtp(ctx context.Context, request VerifyStepUpOtpRequestObject) (VerifyStepUpOtpResponseObject, error)
	// RequestStepUpOtp Send a step-up code to the phone on file (patients; template SMS-01)
	// (POST /v1/auth/step-up/otp-challenges)
	RequestStepUpOtp(ctx context.Context, request RequestStepUpOtpRequestObject) (RequestStepUpOtpResponseObject, error)
	// GetMe Who am I (no personal data beyond IDs and roles)
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListDevices My signed-in devices (S-115)
	// (GET /v1/me/devices)
	ListDevices(ctx context.Context, request ListDevicesRequestObject) (ListDevicesResponseObject, error)
	// SetPushToken Register or replace this device's push token
	// (POST /v1/me/devices/current/push-token)
	SetPushToken(ctx context.Context, request SetPushTokenRequestObject) (SetPushTokenResponseObject, error)
	// ApproveDevice Approve a new device from an already verified one (E-DP-22)
	// (POST /v1/me/devices/{deviceId}/approve)
	ApproveDevice(ctx context.Context, request ApproveDeviceRequestObject) (ApproveDeviceResponseObject, error)
	// RevokeDevice Sign a lost device out (TC-07)
	// (POST /v1/me/devices/{deviceId}/revoke)
	RevokeDevice(ctx context.Context, request RevokeDeviceRequestObject) (RevokeDeviceResponseObject, error)
	// GetProfile My profile (name, date of birth, sex, language, blood group, allergies, emergency contact)
	// (GET /v1/me/profile)
	GetProfile(ctx context.Context, request GetProfileRequestObject) (GetProfileResponseObject, error)
	// PutProfile Create or replace my profile (adults only; no identity numbers in text)
	// (PUT /v1/me/profile)
	PutProfile(ctx context.Context, request PutProfileRequestObject) (PutProfileResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

